/**
 * Runs before every `npm run build`.
 * Fails the build if a hand-maintained public/sitemap.xml reappears.
 *
 * The sitemap is generated by app/sitemap.ts from getPublishedPosts(), which
 * date-filters the publishing queue in content/posts.ts. A static file in
 * public/ collides with that route and, worse, silently lists URLs for posts
 * whose date has not arrived yet -- so Google crawls pages that were never
 * built and logs them as 404s.
 *
 * That is exactly what happened to landscape-lighting-ideas-roanoke-va and
 * spring-lawn-care-checklist-roanoke-va, listed in the old static sitemap and
 * crawled days before their publish dates. Removed in 1dcfab7 (2026-07-28).
 */
const fs = require('fs')
const path = require('path')

const staticSitemap = path.join(__dirname, '..', 'public', 'sitemap.xml')

if (fs.existsSync(staticSitemap)) {
  console.error(
    '\n[sitemap] Build stopped: public/sitemap.xml exists.\n\n' +
      '  The sitemap is generated by app/sitemap.ts. A static file here\n' +
      '  collides with that route and leaks future-dated posts as 404s.\n\n' +
      '  Fix: rm public/sitemap.xml -- never hand-maintain sitemap URLs.\n'
  )
  process.exit(1)
}

console.log('[sitemap] OK - no static public/sitemap.xml')
